import sys, json, subprocess, importlib.util, os, tempfile, re
sys.path.insert(0, sys.argv[1]); OUT=sys.argv[2]
def load(p, n):
    s=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
spec=load(f"{OUT}/cp.py","cp").cp_syntax_spec
tbl=json.load(open(f"{OUT}/annotation/cp.json"))
IO=load(f"{OUT}/annotation/InputOutputInfoGeneratorCp.py","io").InputOutputInfoGeneratorCp
PAR=load(f"{OUT}/annotation/ParallelizabilityInfoGeneratorCp.py","par").ParallelizabilityInfoGeneratorCp
fail=0
def check(c,msg):
    global fail
    if not c: fail+=1; print("FAIL:",msg)
# 1. consistency: flags/options in the syntax spec vs the json table
spec_flags=set(); spec_opts={}
for syntax in spec:
    for n in syntax[0]:
        if n.kind=="Flag": spec_flags|=set(n.spellings())
        else:
            for s in n.spellings(): spec_opts[s]=n
json_flags={s for e in tbl["flag"] for s in (e if isinstance(e,list) else [e])}
json_opts={s for e in tbl["option"] for s in e[:-1]}
check(spec_flags==json_flags, f"flag mismatch {spec_flags^json_flags}")
check(set(spec_opts)==json_opts, f"option mismatch {set(spec_opts)^json_opts}")
# 2. coverage vs --help: every option mentioned in cp --help appears in spec
helptext=subprocess.run(["cp","--help"],capture_output=True,text=True).stdout
help_opts=set(re.findall(r"(?<![\w-])(--?[A-Za-z][\w-]*)", helptext.split("ATTR_LIST is")[0].split("Mandatory arguments")[1]))
help_opts-= {"-dR"}
check(help_opts<=spec_flags|set(spec_opts), f"help options missing from spec: {help_opts-spec_flags-set(spec_opts)}")
check(spec_flags|set(spec_opts)<=help_opts, f"spec options not in help: {(spec_flags|set(spec_opts))-help_opts}")
# 3. binary acceptance tests
W=tempfile.mkdtemp(); open(f"{W}/a","w").write("x\n")
def run(args):
    sub=tempfile.mkdtemp(dir=W); r=subprocess.run(["cp",*args],capture_output=True,text=True,cwd=sub); return r.returncode, r.stderr
for s in sorted(spec_flags):
    rc,err=run([s,f"{W}/a","out"]) if s not in("--help","--version") else (0,"")
    check("invalid option" not in err and "unrecognized" not in err, f"binary rejects flag {s}: {err}")
# every unlisted single letter must be rejected
for ch in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789":
    rc,err=run([f"-{ch}", f"{W}/a","out"])
    accepted="invalid option" not in err
    listed=f"-{ch}" in spec_flags or f"-{ch}" in spec_opts
    check(accepted==listed, f"-{ch}: binary accepted={accepted} spec listed={listed}")
# options: with '=' always; separate word only when not eq-only; choices rejected/accepted
for s,n in sorted(spec_opts.items()):
    vals = n.choices if n.kind=="Selection" else (n.of.choices if n.kind=="List" else ["val"])
    if s in("-t","--target-directory"): vals=["."]
    if s=="--context": vals=[""]
    for v in vals:
        if v=="":
            rc,err=run([s,f"{W}/a","out"])
            check("invalid" not in err and "ambiguous" not in err and "requires an argument" not in err, f"{s} without value rejected: {err}")
            continue
        if s.startswith("--"):
            rc,err=run([f"{s}={v}",f"{W}/a","out"])
            check("invalid" not in err and "ambiguous" not in err, f"{s}={v} rejected: {err}")
        if not n.eq:
            rc,err=run([s,v,f"{W}/a","out"])
            check("invalid" not in err and "ambiguous" not in err and "cannot stat" not in err, f"{s} {v} (separate) rejected: {err}")
        else:
            # eq-only: separate word must be taken as an operand
            rc,err=run([s,"zzz_nofile",f"{W}/a"]) 
            check("cannot stat 'zzz_nofile'" in err or "zzz_nofile" in err, f"{s} unexpectedly consumed a separate word: {err}")
    if n.kind in("Selection",) or n.kind=="List":
        rc,err=run([f"{s}=bogusvalue",f"{W}/a","out"])
        check("invalid argument" in err, f"{s}=bogusvalue not rejected: {err}")
# 4. PaSh-style parse + IO generator simulation
def pash_parse(words):
    flags=[]; ops=[]; i=0; it=iter(range(len(words)))
    while i<len(words):
        w=words[i]
        if "=" in w and w.startswith("--"): w=w.split("=")[0]
        if w in json_flags: flags.append(w); i+=1
        elif w in json_opts: flags.append(w); i+= 1 if "=" in words[i] else 2
        elif re.fullmatch(r"-[a-zA-Z]{2,}",w) and all(f"-{c}" in json_flags for c in w[1:]): flags+= [f"-{c}" for c in w[1:]]; i+=1
        else: ops=words[i:]; break
    return flags,ops
